  function resetExamCreatorMode(){const form=document.getElementById('examFormV6061');if(!form)return;form.reset();form.elements.id.value='';form.querySelector('[data-admin-draft-note]')?.remove();const list=document.getElementById('examQuestionsBuilder');if(list)list.innerHTML=typeof examBuilderCard==='function'?examBuilderCard(0):'';const kicker=document.querySelector('#examCreatorPanel .kicker');if(kicker)kicker.textContent='اختبار جديد';const title=document.querySelector('#examCreatorPanel h3');if(title)title.textContent='البيانات والأسئلة';const submit=form.querySelector('[type="submit"]');if(submit)submit.innerHTML='<span data-icon="clipboard"></span> حفظ ونشر الاختبار';if(typeof updateExamTotal==='function')updateExamTotal();restoreAdminBuilderDraft(form,'exam');}
