  function homeworkQuestionCard(index){return `<article class="exam-builder-question homework-builder-question" data-homework-question><div class="exam-question-head"><b>سؤال <span data-homework-number>${index+1}</span></b><button class="small-btn danger" type="button" onclick="removeHomeworkQuestion(this)">حذف</button></div><div class="exam-meta-grid"><div class="field"><label>نوع السؤال</label><select data-homework-type onchange="updateHomeworkQuestionType(this)"><option value="mcq">اختياري</option><option value="truefalse">صح أو غلط</option><option value="text">مقالي/كتابي</option><option value="code">كتابة كود</option></select></div><div class="field"><label>درجة السؤال</label><input data-homework-mark type="number" min="0.25" step="0.25" value="1" required oninput="updateHomeworkTotal()"></div></div><div class="field"><label>نص السؤال</label><textarea data-homework-text rows="2" required></textarea></div><div data-homework-auto><div class="exam-options-grid">${['أ','ب','ج','د'].map((label,i)=>`<label><span>${label}</span><input data-homework-option="${i}" required placeholder="الاختيار ${label}"></label>`).join('')}</div><div class="field"><label>الإجابة الصحيحة</label><select data-homework-correct required><option value="">حدد الإجابة</option>${[0,1,2,3].map(i=>`<option value="${i}">الاختيار ${i+1}</option>`).join('')}</select></div></div><div data-homework-written hidden><div class="field"><label>الإجابة النموذجية الاختيارية</label><textarea data-homework-model rows="2"></textarea></div><div class="field" data-homework-language hidden><label>لغة البرمجة</label><select data-homework-code-language><option value="python">Python</option><option value="javascript">JavaScript</option><option value="cpp">C++</option><option value="java">Java</option><option value="csharp">C#</option></select></div></div><button class="btn ghost add-question-under" type="button" onclick="addHomeworkQuestionAfter(this)">+ إضافة سؤال تحته</button></article>`;}
  function renumberHomeworkQuestions(){document.querySelectorAll('[data-homework-question]').forEach((card,index)=>{const number=card.querySelector('[data-homework-number]');if(number)number.textContent=index+1;});updateHomeworkTotal();}
  window.addHomeworkQuestion=function(){const list=document.getElementById('homeworkQuestionsBuilder');if(!list)return;list.insertAdjacentHTML('beforeend',homeworkQuestionCard(list.children.length));renumberHomeworkQuestions();};
