  window.updateHomeworkTotal=function(){const total=[...document.querySelectorAll('[data-homework-mark]')].reduce((sum,input)=>sum+(Number(input.value)||0),0),output=document.getElementById('homeworkCalculatedTotal');if(output)output.textContent=total;return total;};
  window.updateHomeworkQuestionType=function(select){const card=select.closest('[data-homework-question]'),type=select.value,auto=card.querySelector('[data-homework-auto]'),written=card.querySelector('[data-homework-written]'),language=card.querySelector('[data-homework-language]'),options=[...card.querySelectorAll('[data-homework-option]')],correct=card.querySelector('[data-homework-correct]');const isAuto=type==='mcq'||type==='truefalse';auto.hidden=!isAuto;written.hidden=isAuto;language.hidden=type!=='code';options.forEach((input,index)=>{const hidden=type==='truefalse'&&index>1;input.closest('label').hidden=hidden;input.required=isAuto&&!hidden;if(type==='truefalse')input.value=index===0?'صح':index===1?'غلط':'';});correct.required=isAuto;if(type==='truefalse')correct.innerHTML='<option value="">حدد الإجابة</option><option value="0">صح</option><option value="1">غلط</option>';else correct.innerHTML='<option value="">حدد الإجابة</option>'+[0,1,2,3].map(i=>`<option value="${i}">الاختيار ${i+1}</option>`).join('');};
  function serializeHomeworkQuestions(){return [...document.querySelectorAll('[data-homework-question]')].map(card=>{const type=card.querySelector('[data-homework-type]').value,question=card.querySelector('[data-homework-text]').value.trim(),mark=Number(card.querySelector('[data-homework-mark]').value||1),choices=[...card.querySelectorAll('[data-homework-option]')].filter(input=>!input.closest('label').hidden).map(input=>input.value.trim()),correctRaw=card.querySelector('[data-homework-correct]').value,correctIndex=correctRaw===''?null:Number(correctRaw),modelAnswer=card.querySelector('[data-homework-model]')?.value.trim()||'',language=card.querySelector('[data-homework-code-language]')?.value||'';if(!question||!mark)return null;if((type==='mcq'||type==='truefalse')&&(choices.length<2||choices.some(value=>!value)||!Number.isInteger(correctIndex)||correctIndex<0||correctIndex>=choices.length))return null;return {type,question,mark,choices:type==='mcq'||type==='truefalse'?choices:[],correctIndex:type==='mcq'||type==='truefalse'?correctIndex:null,modelAnswer,language};});}
  function homeworkSubmissionHTML(row){const answers=Array.isArray(row.answers)?row.answers:[],ready=row.score!==null&&row.score!==undefined&&!row.needsManualReview;return `<details class="assignment-submission-row"><summary><span><b>${safe(row.studentName||'طالب')}</b><small>${safe(row.studentCode||'')} · ${safe(row.homeworkTitle||row.title||'واجب')} · محاولة ${safe(row.attemptNumber||1)}</small></span><span class="badge ${ready?'good':'warn'}">${ready?`${safe(row.score)} من ${safe(row.maxScore||100)}`:'يحتاج تصحيحًا'}</span></summary>${answers.length?`<div class="homework-admin-answer-list">${answers.map((answer,index)=>`<div class="correction-question-v40"><b>${index+1}. ${safe(answer.question||'سؤال')} (${safe(answer.mark||1)} درجة)</b><p>إجابة الطالب: ${safe(answer.answer||'-')}</p><p>النموذج: ${safe(answer.correctAnswer||'تصحيح المدرس')}</p>${row.needsManualReview?`<label>الدرجة المستحقة <input type="number" inputmode="decimal" data-homework-award="${index}" data-submission-id="${safe(row.id)}" min="0" max="${safe(answer.mark||1)}" step="0.25" value="${safe(answer.awardedMark??0)}"></label>`:`<span class="badge ${answer.correct?'good':'danger'}">${answer.correct?'صحيحة':'خاطئة'} · ${safe(answer.awardedMark||0)} من ${safe(answer.mark||1)}</span>`}</div>`).join('')}${row.needsManualReview?`<button class="btn primary" type="button" onclick="saveHomeworkCorrection('${safe(row.id)}',this)">حفظ تصحيح الواجب</button>`:''}</div>`:`<pre>${safe(String(row.answer||'').slice(0,3000)||'لا توجد إجابة نصية.')}</pre>`}<button class="btn ghost" type="button" onclick="grantHomeworkRetakeAdmin('${safe(row.assignmentId)}','${safe(row.studentCode)}')">فتح محاولة إضافية</button></details>`;}
  window.grantHomeworkRetakeAdmin=async function(assignmentId,studentCode){const reason=prompt('اكتب سبب فتح المحاولة الإضافية:','');if(!reason||reason.trim().length<3)return;try{const result=await window.MFCloud?.grantHomeworkRetake?.({assignmentId,studentCode,reason:reason.trim()});if(!result?.ok)throw new Error('لم يؤكد الخادم فتح المحاولة');aToast(`تم فتح المحاولة رقم ${result.attemptNumber}`);}catch(error){aToast(adminActionErrorMessage(error,error?.message||'تعذر فتح المحاولة الإضافية.'));}};
  window.saveHomeworkCorrection=async function(id,button){
    const activeButton=button instanceof HTMLButtonElement?button:null;
    const activeCard=activeButton?.closest('.assignment-submission-row')||null;
    try{
      if(!window.MFCloud?.reviewHomeworkSubmission)throw new Error('Homework review service unavailable');
      const escaped=globalThis.CSS?.escape?CSS.escape(String(id)):String(id).replace(/["\\]/g,'\\$&');
      const inputs=[...document.querySelectorAll(`[data-submission-id="${escaped}"]`)],awarded={};
      if(!inputs.length)throw new Error('لم يتم العثور على درجات التصحيح. افتح الواجب مرة أخرى.');
      inputs.forEach(input=>{const max=Math.max(.25,Number(input.max||1)),value=Number(input.value);if(!Number.isFinite(value)||value<0||value>max)throw new Error(`اكتب درجة صحيحة من 0 إلى ${max}`);awarded[input.dataset.homeworkAward]=value;});
      if(activeButton){activeButton.disabled=true;activeButton.setAttribute('aria-busy','true');activeButton.classList.add('is-loading');activeButton.textContent='جارٍ حفظ التصحيح…';}
      const result=await window.MFCloud.reviewHomeworkSubmission({submissionId:String(id),awarded});
      if(!result?.ok)throw new Error('الخادم لم يؤكد حفظ التصحيح');
      let correctedRow=null,owner=null;
      for(const student of adminData.students||[]){
        const row=(student.homeworks||[]).find(item=>String(item.id)===String(id));
        if(!row)continue;
        row.score=result.score;row.maxScore=result.maxScore;row.needsManualReview=false;row.approved=true;row.status='تم تصحيح الواجب';
        (row.answers||[]).forEach((answer,index)=>{answer.awardedMark=Number(awarded[index]||0);answer.correct=answer.awardedMark===Number(answer.mark||1);answer.teacherReviewed=true;});
        correctedRow=row;owner=student;break;
      }
      saveData(adminData);
      if(activeCard&&correctedRow){
        const shell=document.createElement('div');
        shell.innerHTML=homeworkSubmissionHTML({...correctedRow,studentName:correctedRow.studentName||owner?.name||owner?.studentName,studentCode:correctedRow.studentCode||owner?.studentCode});
        const replacement=shell.firstElementChild;
        if(replacement){replacement.open=true;activeCard.replaceWith(replacement);}
      }
      aToast(`تم حفظ التصحيح: ${result.score} من ${result.maxScore}`);
    }catch(error){aToast(adminActionErrorMessage(error,error?.message&&/درجة|درجات/.test(error.message)?error.message:'تعذر حفظ تصحيح الواجب. لم تتغير الدرجات؛ تحقق من الإنترنت وحاول مرة أخرى.'));}
    finally{if(activeButton?.isConnected){activeButton.disabled=false;activeButton.removeAttribute('aria-busy');activeButton.classList.remove('is-loading');activeButton.textContent='حفظ تصحيح الواجب';}}
  };

