    return `<div class="homework-targeting-card"><div class="exam-meta-grid"><div class="field"><label>إرسال الواجب إلى</label><select name="targetingMode" onchange="updateHomeworkTargetMode(this.value)"><option value="class">صف أو مجموعة كاملة</option><option value="students">طلاب محددون فقط</option></select></div><div class="field" id="homeworkStudentSearchField" hidden><label>البحث عن طالب</label><input id="homeworkStudentSearch" type="search" placeholder="الاسم أو كود الطالب" oninput="filterHomeworkStudentPicker(this.value)"></div></div><div id="homeworkStudentPicker" class="homework-student-picker" hidden><div class="homework-picker-actions"><b>اختر الطلاب المطلوبين</b><button class="small-btn ghost" type="button" onclick="document.querySelectorAll('[data-homework-target-student]:not([hidden]) input').forEach(input=>input.checked=true)">اختيار الظاهر</button><button class="small-btn ghost" type="button" onclick="document.querySelectorAll('[data-homework-target-student] input').forEach(input=>input.checked=false)">إلغاء الكل</button></div>${students.map(student=>{const code=student.studentCode||student.code||student.id||'';return `<label data-homework-target-student data-search="${safe(`${student.name||student.studentName||''} ${code} ${student.grade||''} ${student.group||''}`.toLowerCase())}"><input type="checkbox" value="${safe(code)}"><span><b>${safe(student.name||student.studentName||'طالب')}</b><small>${safe(code)} · ${safe(student.grade||'')} · ${safe(student.group||'بدون مجموعة')}</small></span></label>`;}).join('')||empty('لا يوجد طلاب نشطون.')}</div></div>`;
