  window.updateHomeworkTargetMode=function(mode){const individual=mode==='students',picker=document.getElementById('homeworkStudentPicker'),search=document.getElementById('homeworkStudentSearchField'),form=document.getElementById('assignmentFormV6061');if(picker)picker.hidden=!individual;if(search)search.hidden=!individual;form?.querySelectorAll('select[name="grade"],select[name="group"]').forEach(input=>{input.disabled=individual;input.closest('.field')?.classList.toggle('is-muted',individual);});};
