    fresh();
    const theoryMaterials=(adminData.materials||[]).filter(row=>String(row.lectureCategory||row.materialType||'').toLowerCase()==='theory').slice().reverse();
    content(`<div class="section-head compact-admin-head"><div><span class="kicker"><span data-icon="book-open"></span> محاضرات النظري</span><h2 class="section-title">رفع محاضرات النظري</h2><p class="section-desc">ارفع محاضرة واحدة أو عدة ملفات معًا، وستظهر فقط لطلاب الصف والمجموعة المحددين.</p></div></div>
      <div class="admin-content-workflow-grid">
        <form id="theoryLectureFormV640" class="card admin-workflow-form"><span class="iconbox" data-icon="upload"></span><h3>رفع محاضرات جديدة</h3><div class="field"><label>عنوان أساسي اختياري</label><input name="title" maxlength="180" placeholder="يُستخدم اسم الملف تلقائيًا عند تركه فارغًا"></div><div class="exam-meta-grid"><div class="field"><label>الصف</label><select name="grade">${grades()}</select></div><div class="field"><label>المجموعة</label><select name="group">${targetGroupOptions()}</select></div><div class="field"><label>اسم أو رقم المحاضرة</label><input name="lecture" maxlength="120" placeholder="المحاضرة الثالثة"></div></div><div class="field"><label>وصف مختصر</label><textarea name="desc" rows="3" maxlength="1200"></textarea></div><label class="admin-file-drop"><span><b>اختر PDF أو صورًا</b><small>حتى 10 ملفات، وبحد أقصى 15MB لكل ملف</small></span><input name="file" type="file" accept="application/pdf,.pdf,image/*" multiple required></label><button class="btn primary" type="submit">رفع ونشر المحاضرات</button></form>
      </div><div class="admin-content-lists"><section class="card admin-content-full"><div class="admin-workflow-title"><div><h3>محاضرات النظري المنشورة</h3><p>كل ملف محفوظ مستقل ويمكن فتحه أو حذفه دون التأثير على باقي المحاضرات.</p></div><span class="badge">${theoryMaterials.length}</span></div>${theoryMaterials.map(row=>`<div class="admin-content-row"><div><b>${safe(row.title)}</b><small>${safe(row.grade||'كل المسارات')} ${row.group?`· ${safe(row.group)}`:''} ${row.fileName?`· ${safe(row.fileName)}`:''}</small></div>${row.fileUrl?`<a class="small-btn" href="${safe(row.fileUrl)}" target="_blank" rel="noopener noreferrer">فتح</a>`:''}<button class="small-btn danger" onclick="deleteItem('materials','${safe(row.id)}')">حذف</button></div>`).join('')||empty('لا توجد محاضرات نظري منشورة بعد.')}</section></div>`);
    document.getElementById('theoryLectureFormV640')?.addEventListener('submit',saveTheoryLecturesV640);
    bindAcademicTarget('theoryLectureFormV640');
    hydrateIcons();
